 {"id":"2b0babfd-e417-40ce-b650-3729754dc7df","key":"visitor_reminder","name":"Visitor reminder","subject":"Reminder: {{appointment_type}} on {{appointment_time_local}}","body_html":"<p>Hi {{first_name}},</p><p>This is a reminder that your {{appointment_type}} is scheduled for <strong>{{appointment_time_local}}</strong>.</p><p><a href=\\"{{manage_url}}\\">Manage appointment</a></p>","body_text":"Reminder: your consultation is on {{appointment_time_local}}.","audience":"visitor","enabled":true,"created_at":"2026-07-15T04:40:48.421326+00:00","updated_at":"2026-07-15T04:40:48.421326+00:00"}, 
 {"id":"7b23ee51-754d-4ff1-983b-985f19f106f9","key":"visitor_reschedule","name":"Visitor reschedule confirmation","subject":"Your consultation was rescheduled","body_html":"<p>Hi {{first_name}},</p><p>Your appointment has been rescheduled to <strong>{{appointment_time_local}}</strong>.</p>","body_text":"Your appointment was rescheduled to {{appointment_time_local}}.","audience":"visitor","enabled":true,"created_at":"2026-07-15T04:40:48.421326+00:00","updated_at":"2026-07-15T04:40:48.421326+00:00"}, 
 {"id":"7424ad27-c3ae-47b7-a210-4d40319b3038","key":"visitor_cancellation","name":"Visitor cancellation confirmation","subject":"Your consultation was cancelled","body_html":"<p>Hi {{first_name}},</p><p>Your appointment has been cancelled. If you would like to request a new consultation, visit <a href=\\"{{book_url}}\\">our booking page</a>.</p>","body_text":"Your appointment has been cancelled.","audience":"visitor","enabled":true,"created_at":"2026-07-15T04:40:48.421326+00:00","updated_at":"2026-07-15T04:40:48.421326+00:00"}, 
 {"id":"1a53ba77-4811-4869-896f-e4b270e9d269","key":"visitor_not_eligible","name":"Visitor not eligible follow-up","subject":"Thank you for your interest in Redmont Strategies Group","body_html":"<p>Hi {{first_name}},</p><p>Thank you for your interest. Based on the information provided, a direct strategy consultation may not be the best next step at this time. We may follow up with a more appropriate resource.</p>","body_text":"Thank you for your interest in Redmont Strategies Group.","audience":"visitor","enabled":true,"created_at":"2026-07-15T04:40:48.421326+00:00","updated_at":"2026-07-15T04:40:48.421326+00:00"}, 
 {"id":"9e362c7f-0b18-494c-bd21-4c1bee5dd41d","key":"visitor_manual_review","name":"Visitor manual review","subject":"We are reviewing your consultation request","body_html":"<p>Hi {{first_name}},</p><p>Thank you for submitting your information. Our team will review your request and contact you regarding the best next step.</p>","body_text":"We are reviewing your consultation request.","audience":"visitor","enabled":true,"created_at":"2026-07-15T04:40:48.421326+00:00","updated_at":"2026-07-15T04:40:48.421326+00:00"}, 
