INSERT INTO public.rsg_settings SELECT * FROM json_populate_recordset(NULL::public.rsg_settings, '[{"key":"business_name","value":"Redmont Strategies Group","description":"Company name used in AI speech and messages","updated_at":"2026-07-17T05:51:18.997994+00:00","updated_by":null}, 
