 {"key":"ai_greeting","value":"Thank you for calling Redmont Strategies Group. I''m RSG''s virtual business systems assistant. I can help you learn more about our services, understand which type of system may fit your business, or schedule a consultation. How can I help you today?","description":"Opening line the AI speaks after the recording disclosure","updated_at":"2026-07-17T05:51:18.997994+00:00","updated_by":null}, 
 {"key":"recording_disclosure","value":"This call may be recorded and transcribed to assist with scheduling, service quality, and follow-up.","description":"Played before the greeting when recording is enabled","updated_at":"2026-07-17T05:51:18.997994+00:00","updated_by":null}, 
 {"key":"recording_enabled","value":true,"description":"Whether calls are recorded (configure per applicable law)","updated_at":"2026-07-17T05:51:18.997994+00:00","updated_by":null}, 
 {"key":"voice","value":{"language": "en-US", "provider": "twilio_say", "twilio_voice": "Polly.Joanna-Neural"},"description":"Voice used in turn-based mode; the streaming gateway uses the TTS integration instead","updated_at":"2026-07-17T05:51:18.997994+00:00","updated_by":null}, 
