INSERT INTO public.rsg_message_templates SELECT * FROM json_populate_recordset(NULL::public.rsg_message_templates, E'[{"key":"booking_confirmation_sms","channel":"sms","name":"Booking confirmation (SMS)","subject":null,"body":"Hi {{first_name}}, you''re confirmed for a {{consultation_name}} with Redmont Strategies Group on {{date_time}} ({{timezone_abbr}}). Confirmation code: {{confirmation_code}}. Need changes? Call {{rsg_phone}}.","description":"Sent immediately after a booking","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}, 
 {"key":"booking_confirmation_email","channel":"email","name":"Booking confirmation (email)","subject":"Confirmed: {{consultation_name}} — {{date_time}}","body":"Hello {{first_name}},\\n\\nYour {{consultation_name}} with Redmont Strategies Group is confirmed.\\n\\nWhen: {{date_time}} ({{timezone_name}})\\nWith: {{staff_name}}\\nConfirmation code: {{confirmation_code}}\\n\\nWhat we''ll cover: {{summary}}\\n\\nNeed to reschedule? Call {{rsg_phone}} and our assistant can handle it, or reply to this email.\\n\\n— Redmont Strategies Group\\nTechnology, AI automation, and business systems","description":"Sent after booking when an email address is on file","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}, 
 {"key":"reminder_sms","channel":"sms","name":"Appointment reminder (SMS)","subject":null,"body":"Reminder from Redmont Strategies Group: your {{consultation_name}} is {{relative_time}} — {{date_time}} ({{timezone_abbr}}). Code {{confirmation_code}}. Reply C to confirm or call {{rsg_phone}} to change.","description":"Sent at each configured reminder offset","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}, 
 {"key":"reminder_email","channel":"email","name":"Appointment reminder (email)","subject":"Reminder: {{consultation_name}} {{relative_time}}","body":"Hello {{first_name}},\\n\\nA quick reminder that your {{consultation_name}} with Redmont Strategies Group is {{relative_time}}:\\n\\n{{date_time}} ({{timezone_name}})\\nWith: {{staff_name}}\\nConfirmation code: {{confirmation_code}}\\n\\nTalk soon,\\nRedmont Strategies Group","description":"Email reminder","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}, 
 {"key":"reschedule_sms","channel":"sms","name":"Reschedule confirmation (SMS)","subject":null,"body":"Updated: your {{consultation_name}} with Redmont Strategies Group is now {{date_time}} ({{timezone_abbr}}). Confirmation code: {{confirmation_code}}.","description":"Sent after a reschedule","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}, 
 {"key":"cancellation_sms","channel":"sms","name":"Cancellation confirmation (SMS)","subject":null,"body":"Your {{consultation_name}} with Redmont Strategies Group on {{date_time}} has been cancelled. If you''d like to rebook, call {{rsg_phone}} anytime.","description":"Sent after a cancellation","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}, 
 {"key":"missed_call_sms","channel":"sms","name":"Missed-call recovery (SMS)","subject":null,"body":"Hi, this is Redmont Strategies Group — sorry we missed each other. If you''d like help with your business systems or want to book a consultation, call {{rsg_phone}} and our assistant can set it up in a couple of minutes.","description":"Sent when a call drops before anything was completed","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}, 
 {"key":"callback_confirmation_sms","channel":"sms","name":"Callback confirmation (SMS)","subject":null,"body":"Redmont Strategies Group: we''ve logged your callback request ({{reference_code}}). A team member will reach out {{preferred_window}}.","description":"Sent after the AI takes a callback request","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}, 
 {"key":"ticket_confirmation_sms","channel":"sms","name":"Support ticket confirmation (SMS)","subject":null,"body":"Redmont Strategies Group support: ticket {{reference_code}} created — {{subject}}. We''ll follow up shortly.","description":"Sent after a support ticket is created by phone","active":true,"updated_at":"2026-07-17T05:51:18.997994+00:00"}]'::json);
